/// Device buffer backed by a `cudarc::driver::CudaSlice<u8>`.
///
/// `len` is the count of `T` elements; the underlying byte slice has
/// `len * size_of::<T>()` bytes. Zero-length buffers carry `inner = None`
/// because cudarc rejects zero-byte allocations.
pub struct CudaBuffer<T: BufferElement> {
    inner: Option<CudaSlice<u8>>,
    len: usize,
    _allocation: Option<CudaAllocationGuard>,
    _marker: PhantomData<T>,
}

type CudaAllocationStats = BackendAllocationLedger;
type CudaAllocationGuard = BackendAllocationGuard;

struct TrackedCudaSlice {
    inner: CudaSlice<u8>,
    _allocation: CudaAllocationGuard,
}

impl Deref for TrackedCudaSlice {
    type Target = CudaSlice<u8>;

    fn deref(&self) -> &Self::Target {
        &self.inner
    }
}

impl DerefMut for TrackedCudaSlice {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.inner
    }
}

/// Device-resident `Complex32` dense LU factorization backed by cuSOLVERDN.
///
/// The factor matrix is stored in column-major order, matching LAPACK and
/// cuSOLVERDN. This is intended for tiny AMG coarse-grid solves where keeping
/// the solve on the CUDA stream is more important than sparse storage.
pub struct CudaDenseLuC32 {
    n: usize,
    factors: CudaBuffer<Complex32>,
    ipiv: CudaBuffer<i32>,
    info: Mutex<CudaBuffer<i32>>,
    workspace: CudaBuffer<Complex32>,
}

/// Device-resident `Complex64` dense LU factorization backed by cuSOLVERDN.
///
/// The factor matrix is stored in column-major order.  Keeping the factors,
/// pivots, and solve workspace on the device gives CUDA BEM gates an explicit
/// Complex64 solve boundary instead of silently dropping to a host solve.
pub struct CudaDenseLuC64 {
    valid: bool,
    n: usize,
    factors: CudaBuffer<Complex64>,
    ipiv: CudaBuffer<i32>,
    info: Mutex<CudaBuffer<i32>>,
    workspace: CudaBuffer<Complex64>,
}

/// Device-resident `f64` dense LU factorization backed by cuSOLVERDN
/// (`cusolverDnDgetrf`/`Dgetrs`).
///
/// Column-major factors, mirroring [`CudaDenseLuC64`]. This is the device
/// counterpart of the host blocked `lu_factorize`: host code uploads a
/// column-major copy, factors and solves on the stream, and downloads the
/// result.
pub struct CudaDenseLuF64 {
    n: usize,
    factors: CudaBuffer<f64>,
    ipiv: CudaBuffer<i32>,
    info: Mutex<CudaBuffer<i32>>,
    workspace: CudaBuffer<f64>,
}

impl CudaDenseLuC32 {
    pub fn n(&self) -> usize {
        self.n
    }

    pub fn workspace_len(&self) -> usize {
        self.workspace.len
    }
}

impl CudaDenseLuC64 {
    /// Matrix dimension of the factorization.
    pub fn n(&self) -> usize {
        self.n
    }

    /// Number of Complex64 workspace elements retained on the device.
    pub fn workspace_len(&self) -> usize {
        self.workspace.len
    }
}

impl CudaDenseLuF64 {
    /// Matrix dimension of the factorization.
    pub fn n(&self) -> usize {
        self.n
    }

    /// Number of f64 workspace elements retained on the device.
    pub fn workspace_len(&self) -> usize {
        self.workspace.len
    }
}

/// Device-resident `f64` dense Cholesky factorization (cuSOLVERDN
/// `cusolverDnDpotrf`/`Dpotrs`, lower triangle).
///
/// Column-major factors, mirroring [`CudaDenseLuF64`] minus the pivot
/// array (Cholesky has no pivoting). Factored with `CUBLAS_FILL_MODE_LOWER`,
/// matching the host blocked `cholesky_factorize`.
pub struct CudaDenseCholF64 {
    n: usize,
    factors: CudaBuffer<f64>,
    info: Mutex<CudaBuffer<i32>>,
    workspace: CudaBuffer<f64>,
}

impl CudaDenseCholF64 {
    /// Matrix dimension of the factorization.
    pub fn n(&self) -> usize {
        self.n
    }

    /// Number of f64 workspace elements retained on the device.
    pub fn workspace_len(&self) -> usize {
        self.workspace.len
    }
}

impl<T: BufferElement> CudaBuffer<T> {
    /// Borrow the underlying byte slice; `None` for zero-length.
    pub fn raw(&self) -> Option<&CudaSlice<u8>> {
        self.inner.as_ref()
    }

    /// Mutably borrow the underlying byte slice; `None` for zero-length.
    pub fn raw_mut(&mut self) -> Option<&mut CudaSlice<u8>> {
        self.inner.as_mut()
    }
}

/// Validate a public one-dimensional view immediately before binding it to a
/// CUDA kernel.  `BufferView` is intentionally copyable (callers may build it
/// from deserialised metadata), so native entry points must not rely only on
/// the constructor having been used.  Keeping the allocation-bound check here
/// also gives all specialised kernels the same offset/stride contract as the
/// generic view operations.
fn validate_cuda_buffer_view<T: BufferElement>(
    operation: &'static str,
    buffer: &CudaBuffer<T>,
    view: BufferView,
) -> BackendResult<()> {
    if view.stride == 0 {
        return Err(BackendError::InvalidArgument {
            operation,
            reason: "view stride must be non-zero".into(),
        });
    }
    let end = view
        .checked_end_exclusive()
        .map_err(|error| BackendError::InvalidArgument {
            operation,
            reason: format!("invalid view bounds: {error}"),
        })?;
    if end > buffer.len {
        return Err(BackendError::InvalidArgument {
            operation,
            reason: format!(
                "view end {end} exceeds buffer length {} (offset {}, len {}, stride {})",
                buffer.len, view.offset, view.len, view.stride
            ),
        });
    }
    view.descriptor::<T>("cuda")
        .map_err(|error| BackendError::InvalidArgument {
            operation,
            reason: format!("invalid view descriptor: {error}"),
        })?;
    Ok(())
}

fn view_u64(operation: &'static str, value: usize, field: &str) -> BackendResult<u64> {
    u64::try_from(value).map_err(|_| BackendError::InvalidArgument {
        operation,
        reason: format!("{field} exceeds CUDA address range"),
    })
}

impl<T: BufferElement> DeviceBufferLike<T> for CudaBuffer<T> {
    fn len(&self) -> usize {
        self.len
    }
}

