struct CudaEventCompletion {
    event: CudaEvent,
    pending_error: Arc<Mutex<Option<BackendError>>>,
    failure_injection: Arc<Mutex<Option<CudaFailureInjectionPoint>>>,
    runtime_stats: Arc<CudaRuntimeStats>,
}

impl Drop for CudaEventCompletion {
    fn drop(&mut self) {
        // The CUDA event is owned by this completion token.  Keep the live
        // driver-resource count accurate even when a caller abandons a token
        // without waiting on it (the stream ordering remains owned by CUDA).
        self.runtime_stats.release_completion_event();
    }
}

impl BackendCompletion for CudaEventCompletion {
    fn wait(&mut self) -> BackendResult<()> {
        self.runtime_stats.record_completion_wait();
        // A legacy operation may have retained an asynchronous error after
        // this completion token was submitted.  Do not wait on (or report)
        // the event as successful in that state: the first retained error is
        // the authoritative completion result and the caller must recover or
        // recreate the backend according to its disposition.
        check_pending_error_slot(&self.pending_error)?;
        if let Err(error) = take_cuda_failure(
            &self.failure_injection,
            CudaFailureInjectionPoint::DeviceLoss,
        ) {
            record_first_pending_error(&self.pending_error, error.clone());
            return Err(error);
        }
        if let Err(error) = take_cuda_failure(
            &self.failure_injection,
            CudaFailureInjectionPoint::EventWait,
        ) {
            record_first_pending_error(&self.pending_error, error.clone());
            return Err(error);
        }
        self.event.synchronize().map_err(|error| {
            self.runtime_stats.record_failed_synchronization();
            backend_driver_synchronization_error(
                &self.pending_error,
                "completion_event",
                format!("{error:?}"),
            )
        })?;
        self.pending_error
            .lock()
            .map_err(|_| BackendError::OperationFailed {
                operation: "cuda_error_state",
                reason: "pending error mutex poisoned".into(),
            })?
            .as_ref()
            .cloned()
            .map_or(Ok(()), Err)
    }
}

/// Runtime counters for one CUDA backend instance.
///
/// The counters are deliberately submission-oriented: a library operation is
/// counted when cuBLAS/cuSPARSE/cuSOLVER is called, and a kernel launch is
/// counted when cudarc encodes a custom kernel.  They are useful as a stable
/// per-solve trace without requiring Nsight, while the allocation and
/// transfer fields retain the same quota/checked-transfer accounting used by
/// the backend itself.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct CudaRuntimeStatsSnapshot {
    pub kernel_launches: usize,
    pub library_operations: usize,
    pub synchronization_calls: usize,
    pub failed_synchronizations: usize,
    pub completion_events: usize,
    pub completion_waits: usize,
    pub allocation_operations: usize,
    pub staging_allocation_operations: usize,
    pub transfer: TransferStatsSnapshot,
    pub live_allocation_bytes: usize,
    pub allocation_high_water_bytes: usize,
    pub live_staging_bytes: usize,
    pub staging_high_water_bytes: usize,
    /// Live driver-owned resources and the measured initialization-time
    /// memory exemption.  Caller-visible buffers and workspaces remain in
    /// the byte ledger above; this nested record accounts for resources the
    /// CUDA driver owns directly and cannot expose as byte allocations.
    pub driver_resources: CudaDriverResourceStatsSnapshot,
}

/// Shared allocation ledger retained across backend teardown.
///
/// The speaker production report samples residency while its backend-owned
/// work buffers are still in scope.  A caller that needs to prove RAII
/// cleanup can retain this handle, let the backend and its buffers drop, and
/// then take a second snapshot without reopening a CUDA context.
#[derive(Clone)]
pub struct CudaAllocationLedger {
    allocation_stats: Arc<CudaAllocationStats>,
    staging_stats: Arc<CudaAllocationStats>,
}

impl CudaAllocationLedger {
    pub fn snapshot(&self) -> BackendMemoryStatsSnapshot {
        BackendMemoryStatsSnapshot {
            live_allocation_bytes: self.allocation_stats.live_bytes.load(Ordering::Acquire),
            allocation_high_water_bytes: self
                .allocation_stats
                .high_water_bytes
                .load(Ordering::Acquire),
            live_staging_bytes: self.staging_stats.live_bytes.load(Ordering::Acquire),
            staging_high_water_bytes: self.staging_stats.high_water_bytes.load(Ordering::Acquire),
        }
    }
}

/// Snapshot of CUDA resources that are owned by the driver rather than by a
/// `CudaBuffer`/`TrackedCudaSlice` byte ledger.
///
/// `measured_driver_bytes` is the free-memory delta observed between the
/// context/stream baseline and completion of backend initialization.  It is a
/// bounded exemption for context, stream, loaded modules, and library
/// handles; subsequent user/workspace allocations are accounted separately.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct CudaDriverResourceStatsSnapshot {
    pub live_contexts: usize,
    pub live_streams: usize,
    pub live_modules: usize,
    pub live_dynamic_libraries: usize,
    pub live_library_handles: usize,
    pub live_fft_plans: usize,
    pub live_completion_events: usize,
    /// Free bytes sampled after the context and stream exist, before loading
    /// backend modules and creating vendor handles.
    pub initialization_baseline_free_bytes: usize,
    /// Free bytes sampled after backend-owned modules and handles initialise.
    pub initialization_free_bytes: usize,
    /// Difference between the two free-memory readings above.  This is a
    /// measured driver-resource exemption, not an allocation quota bypass.
    pub measured_driver_bytes: usize,
}

impl CudaRuntimeStatsSnapshot {
    /// Return the counters attributable to one solve or workload interval.
    ///
    /// Live bytes are sampled at the end of the interval.  High-water marks
    /// remain absolute so the result can still be compared with the backend's
    /// configured quota; event counters and transfer counts are deltas.
    pub fn since(self, earlier: Self) -> Self {
        Self {
            kernel_launches: self.kernel_launches.saturating_sub(earlier.kernel_launches),
            library_operations: self
                .library_operations
                .saturating_sub(earlier.library_operations),
            synchronization_calls: self
                .synchronization_calls
                .saturating_sub(earlier.synchronization_calls),
            failed_synchronizations: self
                .failed_synchronizations
                .saturating_sub(earlier.failed_synchronizations),
            completion_events: self
                .completion_events
                .saturating_sub(earlier.completion_events),
            completion_waits: self
                .completion_waits
                .saturating_sub(earlier.completion_waits),
            allocation_operations: self
                .allocation_operations
                .saturating_sub(earlier.allocation_operations),
            staging_allocation_operations: self
                .staging_allocation_operations
                .saturating_sub(earlier.staging_allocation_operations),
            transfer: self.transfer.saturating_sub(earlier.transfer),
            live_allocation_bytes: self.live_allocation_bytes,
            allocation_high_water_bytes: self.allocation_high_water_bytes,
            live_staging_bytes: self.live_staging_bytes,
            staging_high_water_bytes: self.staging_high_water_bytes,
            driver_resources: self.driver_resources,
        }
    }
}

#[derive(Debug, Default)]
struct CudaRuntimeStats {
    kernel_launches: AtomicUsize,
    library_operations: AtomicUsize,
    synchronization_calls: AtomicUsize,
    failed_synchronizations: AtomicUsize,
    completion_events: AtomicUsize,
    completion_waits: AtomicUsize,
    active_completion_events: AtomicUsize,
}

impl CudaRuntimeStats {
    fn record_kernel_launch(&self) {
        self.kernel_launches.fetch_add(1, Ordering::Relaxed);
    }

    fn record_library_operation(&self) {
        self.library_operations.fetch_add(1, Ordering::Relaxed);
    }

    fn record_synchronization(&self) {
        self.synchronization_calls.fetch_add(1, Ordering::Relaxed);
    }

    fn record_failed_synchronization(&self) {
        self.failed_synchronizations.fetch_add(1, Ordering::Relaxed);
    }

    fn record_completion_event(&self) {
        self.completion_events.fetch_add(1, Ordering::Relaxed);
        self.active_completion_events
            .fetch_add(1, Ordering::Relaxed);
    }

    fn record_completion_wait(&self) {
        self.completion_waits.fetch_add(1, Ordering::Relaxed);
    }

    fn release_completion_event(&self) {
        self.active_completion_events
            .fetch_sub(1, Ordering::Relaxed);
    }

    fn reset(&self) {
        self.kernel_launches.store(0, Ordering::Release);
        self.library_operations.store(0, Ordering::Release);
        self.synchronization_calls.store(0, Ordering::Release);
        self.failed_synchronizations.store(0, Ordering::Release);
        self.completion_events.store(0, Ordering::Release);
        self.completion_waits.store(0, Ordering::Release);
    }
}

fn record_first_pending_error(slot: &Mutex<Option<BackendError>>, error: BackendError) {
    if let Ok(mut pending_error) = slot.lock()
        && pending_error.is_none()
    {
        *pending_error = Some(error);
    }
}

fn check_pending_error_slot(slot: &Mutex<Option<BackendError>>) -> BackendResult<()> {
    slot.lock()
        .map_err(|_| BackendError::OperationFailed {
            operation: "cuda_error_state",
            reason: "pending error mutex poisoned".into(),
        })?
        .as_ref()
        .cloned()
        .map_or(Ok(()), Err)
}

/// CUDA backend. One primary context + one stream + one cuBLAS handle +
/// one cuSPARSE handle per backend instance.
pub struct CudaBackend {
    ctx: Arc<CudaContext>,
    stream: Arc<CudaStream>,
    /// First failure retained by legacy void operations. CUDA driver and
    /// library errors can be returned synchronously by the checked path, but
    /// the historical trait methods have no result slot; retaining the error
    /// prevents a later checked call from observing a false success.
    pending_error: Arc<Mutex<Option<BackendError>>>,
    /// One-shot fault injection for checked preconditioner acceptance tests.
    preconditioner_failure: Arc<Mutex<Option<PreconditionerFailureInjectionPoint>>>,
    /// One-shot fault injection for native CUDA resource and completion seams.
    failure_injection: Arc<Mutex<Option<CudaFailureInjectionPoint>>>,
    cast_kernels: Option<CudaCastKernels>,
    validation_kernels: Option<CudaValidationKernels>,
    real_transform_kernels: Option<CudaRealTransformKernels>,
    bem_kernels: Option<CudaBemKernels>,
    fmm_kernels: Option<CudaFmmKernels>,
    multi_dot_kernels: Option<CudaMultiDotKernels>,
    local_kernels: Option<CudaLocalKernels>,
    fused_numeric_combinations: bool,
    csr_preprocess: Option<csr_preprocess::CsrPreprocess>,
    pub(super) hex_kernels: Mutex<Option<Arc<super::fem_hex::CudaHexKernels>>>,
    pub(super) tet_kernels: Mutex<[Option<Arc<super::fem_tet::CudaTetKernels>>; 2]>,
    pub(super) quadrature_kernel: Mutex<Option<Arc<CudaFunction>>>,
    multi_dot_workspace: Mutex<CudaMultiDotWorkspace>,
    real_transform_workspace: Mutex<CudaRealTransformWorkspace>,
    allocation_stats: Arc<CudaAllocationStats>,
    staging_stats: Arc<CudaAllocationStats>,
    transfer_stats: Arc<BackendTransferStats>,
    runtime_stats: Arc<CudaRuntimeStats>,
    blas: cublas_sys::cublasHandle_t,
    solver: cusolver_sys::cusolverDnHandle_t,
    sparse: cusparse_sys::cusparseHandle_t,
    total_bytes: usize,
    /// Free-memory readings around backend-owned driver resources.  The
    /// difference is reported as a measured exemption because the CUDA
    /// driver does not expose byte sizes for contexts, streams, modules, or
    /// BLAS/Sparse/Solver handles.
    driver_memory_before_bytes: usize,
    driver_memory_after_bytes: usize,
    fft: Option<CudaFft>,
}

/// Replayable CUDA graph captured from a stable sequence of backend calls.
///
/// The captured buffers and descriptors are owned by the caller, so they must
/// outlive this handle and every replay. This is intended for repeated
/// Krylov/relaxation segments where dimensions, CSR descriptors, and vector
/// buffers stay fixed while the same stream work is launched many times.
pub struct CudaGraphReplay {
    graph: CudaGraph,
    pending_error: Arc<Mutex<Option<BackendError>>>,
    failure_injection: Arc<Mutex<Option<CudaFailureInjectionPoint>>>,
    runtime_stats: Arc<CudaRuntimeStats>,
}

/// RAII guard for CUDA stream capture.  Checked capture APIs use this guard
/// instead of catching user callback panics: normal error paths finish and
/// inspect capture teardown explicitly, while unwinding still leaves the
/// stream capture state cleaned up by `Drop`.
struct CudaCaptureGuard<'a> {
    stream: &'a Arc<CudaStream>,
    pending_error: &'a Mutex<Option<BackendError>>,
    failure_injection: &'a Mutex<Option<CudaFailureInjectionPoint>>,
    active: bool,
}

impl CudaCaptureGuard<'_> {
    fn finish(&mut self) -> Result<Option<CudaGraph>, DriverError> {
        self.active = false;
        self.stream.end_capture(
            cuda_driver_sys::CUgraphInstantiate_flags::CUDA_GRAPH_INSTANTIATE_FLAG_AUTO_FREE_ON_LAUNCH,
        )
    }
}

impl Drop for CudaCaptureGuard<'_> {
    fn drop(&mut self) {
        if self.active {
            if let Err(error) =
                take_cuda_failure(self.failure_injection, CudaFailureInjectionPoint::Teardown)
            {
                record_teardown_error(self.pending_error, error);
            }
            if let Err(error) = self.stream.end_capture(
                cuda_driver_sys::CUgraphInstantiate_flags::CUDA_GRAPH_INSTANTIATE_FLAG_AUTO_FREE_ON_LAUNCH,
            ) {
                record_teardown_error(
                    self.pending_error,
                    BackendError::OperationFailed {
                        operation: "cuda_graph_abort_capture",
                        reason: format!("{error:?}"),
                    },
                );
            }
        }
    }
}

impl CudaGraphReplay {
    /// Replay the captured graph on the backend stream it was captured from.
    pub fn launch(&self) -> Result<(), OomError> {
        self.try_launch().map_err(backend_error_to_oom)
    }

    /// Upload graph resources explicitly before the first replay.
    pub fn upload(&self) -> Result<(), OomError> {
        self.try_upload().map_err(backend_error_to_oom)
    }

    /// Checked graph replay. A driver failure is retained in the owning
    /// backend's first-error slot, so subsequent checked work cannot report a
    /// false success after a failed replay.
    pub fn try_launch(&self) -> BackendResult<()> {
        check_pending_error_slot(&self.pending_error)?;
        if let Err(error) =
            take_cuda_failure(&self.failure_injection, CudaFailureInjectionPoint::Launch)
        {
            record_first_pending_error(&self.pending_error, error.clone());
            return Err(error);
        }
        self.runtime_stats.record_kernel_launch();
        self.graph.launch().map_err(|error| {
            backend_driver_launch_error(
                &self.pending_error,
                "cuda_graph_launch",
                format!("{error:?}"),
            )
        })
    }

    /// Checked graph resource upload.
    pub fn try_upload(&self) -> BackendResult<()> {
        check_pending_error_slot(&self.pending_error)?;
        self.runtime_stats.record_library_operation();
        self.graph.upload().map_err(|error| {
            backend_driver_launch_error(
                &self.pending_error,
                "cuda_graph_upload",
                format!("{error:?}"),
            )
        })
    }
}

