/// Device-resident constant-basis triangular BEM field evaluator.
///
/// Geometry and constant pressure/normal-velocity traces are uploaded once at
/// construction.  [`Self::try_apply_device`] then evaluates a whole point
/// batch without host staging; [`Self::try_apply`] is the explicit host
/// convenience wrapper for callers that need a `Vec` result.
pub struct CudaBemFieldOperatorC64 {
    pool: MemoryPool<CudaBackend>,
    elements: Buffer<BemFieldElementC64, CudaBackend>,
    wave_number: f64,
    harmonic_factor: f64,
    pressure_factor: f64,
    workspace: Mutex<Option<Buffer<Complex64, CudaBackend>>>,
}

/// Device-resident Complex64 regular triangle-pair evaluator.
///
/// The pair geometry is uploaded once at construction.  Repeated device
/// applications reuse that geometry and a persistent output workspace; the
/// only publication boundary is the caller-provided output buffer.  This is
/// the residency-preserving counterpart to
/// [`CudaBackend::try_bem_regular_pair_c64_batch`].
pub struct CudaBemRegularPairOperatorC64 {
    pool: MemoryPool<CudaBackend>,
    pairs: Buffer<BemRegularPairInF64, CudaBackend>,
    wave_number: f64,
    harmonic_factor: f64,
    workspace: Mutex<Option<Buffer<BemRegularPairOutF64, CudaBackend>>>,
}

/// Device-resident Complex64 BEM pair evaluator driven by precomputed
/// quadrature geometry.
///
/// This is the checked CUDA seam for regular, quasi-singular, Duffy bulk, and
/// regularised hypersingular-edge pairs.  Host code may choose an integration
/// chart and upload its points/weights, but the kernel performs every kernel
/// evaluation and accumulation on the device.  Pair and sample buffers are
/// retained for repeated RHS/frequency actions.
pub struct CudaBemQuadratureOperatorC64 {
    pool: MemoryPool<CudaBackend>,
    pairs: Buffer<BemQuadraturePairC64, CudaBackend>,
    samples: Buffer<BemQuadratureSampleC64, CudaBackend>,
    wave_number: f64,
    harmonic_factor: f64,
    workspace: Mutex<Option<Buffer<BemRegularPairOutF64, CudaBackend>>>,
}

