    /// Enqueue an indexed dense translation:
    /// `dst[dst_indices[i]] += Σ_j A[i,j] * src[src_indices[j]]`.
    ///
    /// Matrix data is row-major with `lda` elements per row.  The operation is
    /// one CUDA thread per output row, which keeps each destination write
    /// deterministic and makes the uniqueness contract on `dst_indices`
    /// explicit.  Index entries outside the source/destination buffers are
    /// ignored by the kernel, as in the CPU/Metal helpers.
    #[allow(clippy::too_many_arguments)]
    pub fn try_fmm_indexed_dense_matvec_accumulate_c64(
        &self,
        matrix: &CudaBuffer<Complex64>,
        rows: usize,
        cols: usize,
        lda: usize,
        src: &CudaBuffer<Complex64>,
        src_indices: &CudaBuffer<i32>,
        dst: &mut CudaBuffer<Complex64>,
        dst_indices: &CudaBuffer<i32>,
    ) -> BackendResult<()> {
        self.check_pending_error()?;
        let operation = "fmm_indexed_dense_matvec_accumulate_c64";
        if lda < cols {
            return Err(BackendError::InvalidArgument {
                operation,
                reason: format!("leading dimension {lda} is smaller than column count {cols}"),
            });
        }
        if rows > dst_indices.len || cols > src_indices.len {
            return Err(BackendError::InvalidArgument {
                operation,
                reason: "logical shape exceeds index-list lengths".into(),
            });
        }
        let required = if rows == 0 {
            0
        } else {
            (rows - 1)
                .checked_mul(lda)
                .and_then(|offset| offset.checked_add(cols))
                .ok_or_else(|| BackendError::InvalidArgument {
                    operation,
                    reason: "matrix span overflows usize".into(),
                })?
        };
        if matrix.len < required {
            return Err(BackendError::InvalidArgument {
                operation,
                reason: format!(
                    "matrix length {} is smaller than required span {required}",
                    matrix.len
                ),
            });
        }
        if rows == 0 {
            return Ok(());
        }
        let rows = u32::try_from(rows).map_err(|_| BackendError::InvalidArgument {
            operation,
            reason: "row count exceeds CUDA kernel dimension range".into(),
        })?;
        let cols = u32::try_from(cols).map_err(|_| BackendError::InvalidArgument {
            operation,
            reason: "column count exceeds CUDA kernel dimension range".into(),
        })?;
        let lda = u32::try_from(lda).map_err(|_| BackendError::InvalidArgument {
            operation,
            reason: "leading dimension exceeds CUDA kernel dimension range".into(),
        })?;
        let src_len = u32::try_from(src.len).map_err(|_| BackendError::InvalidArgument {
            operation,
            reason: "source length exceeds CUDA kernel dimension range".into(),
        })?;
        let dst_len = u32::try_from(dst.len).map_err(|_| BackendError::InvalidArgument {
            operation,
            reason: "destination length exceeds CUDA kernel dimension range".into(),
        })?;
        let kernels = self.fmm_kernels.as_ref().ok_or(BackendError::Unsupported {
            backend: "cuda",
            operation,
            scalar: "Complex64",
        })?;
        let matrix_raw = matrix.raw().ok_or(BackendError::InvalidArgument {
            operation,
            reason: "matrix buffer is unexpectedly empty".into(),
        })?;
        let src_raw = src.raw().ok_or(BackendError::InvalidArgument {
            operation,
            reason: "source buffer is unexpectedly empty".into(),
        })?;
        let src_indices_raw = src_indices.raw().ok_or(BackendError::InvalidArgument {
            operation,
            reason: "source-index buffer is unexpectedly empty".into(),
        })?;
        let dst_raw = dst.raw_mut().ok_or(BackendError::InvalidArgument {
            operation,
            reason: "destination buffer is unexpectedly empty".into(),
        })?;
        let dst_indices_raw = dst_indices.raw().ok_or(BackendError::InvalidArgument {
            operation,
            reason: "destination-index buffer is unexpectedly empty".into(),
        })?;
        self.runtime_stats.record_kernel_launch();
        unsafe {
            self.stream
                .launch_builder(&kernels.indexed_dense_matvec_accum_c64)
                .arg(matrix_raw)
                .arg(src_raw)
                .arg(src_indices_raw)
                .arg(dst_raw)
                .arg(dst_indices_raw)
                .arg(&rows)
                .arg(&cols)
                .arg(&lda)
                .arg(&src_len)
                .arg(&dst_len)
                .launch(LaunchConfig {
                    grid_dim: (rows, 1, 1),
                    block_dim: (1, 1, 1),
                    shared_mem_bytes: 0,
                })
                .map_err(|error| {
                    backend_driver_launch_error(
                        &self.pending_error,
                        operation,
                        format!("{error:?}"),
                    )
                })?;
        }
        Ok(())
    }

