    /// Enqueue an indexed dense FMM translation over checked strided value
    /// and index views.  Matrix columns remain contiguous and `lda` supplies
    /// the physical row stride; `matrix_offset` selects a submatrix inside a
    /// larger device allocation.
    #[allow(clippy::too_many_arguments)]
    pub fn try_fmm_indexed_dense_matvec_accumulate_c64_view(
        &self,
        matrix: &CudaBuffer<Complex64>,
        matrix_offset: usize,
        rows: usize,
        cols: usize,
        lda: usize,
        src: &CudaBuffer<Complex64>,
        src_view: BufferView,
        src_indices: &CudaBuffer<i32>,
        src_indices_view: BufferView,
        dst: &mut CudaBuffer<Complex64>,
        dst_view: BufferView,
        dst_indices: &CudaBuffer<i32>,
        dst_indices_view: BufferView,
    ) -> BackendResult<()> {
        self.check_pending_error()?;
        let operation = "fmm_indexed_dense_matvec_accumulate_c64_view";
        if lda < cols || rows > dst_indices_view.len || cols > src_indices_view.len {
            return Err(BackendError::InvalidArgument {
                operation,
                reason: "invalid matrix leading dimension or index-view length".into(),
            });
        }
        validate_cuda_buffer_view(operation, src, src_view)?;
        validate_cuda_buffer_view(operation, src_indices, src_indices_view)?;
        validate_cuda_buffer_view(operation, dst, dst_view)?;
        validate_cuda_buffer_view(operation, dst_indices, dst_indices_view)?;
        let matrix_end = if rows == 0 {
            matrix_offset
        } else {
            matrix_offset
                .checked_add((rows - 1).checked_mul(lda).ok_or_else(|| {
                    BackendError::InvalidArgument {
                        operation,
                        reason: "matrix row span overflows usize".into(),
                    }
                })?)
                .and_then(|end| end.checked_add(cols))
                .ok_or_else(|| BackendError::InvalidArgument {
                    operation,
                    reason: "matrix span overflows usize".into(),
                })?
        };
        if matrix_end > matrix.len {
            return Err(BackendError::InvalidArgument {
                operation,
                reason: format!(
                    "matrix view end {matrix_end} exceeds buffer length {}",
                    matrix.len
                ),
            });
        }
        if rows == 0 {
            return Ok(());
        }
        let kernels = self.fmm_kernels.as_ref().ok_or(BackendError::Unsupported {
            backend: "cuda",
            operation,
            scalar: "Complex64",
        })?;
        let rows_u64 = view_u64(operation, rows, "row count")?;
        let cols_u64 = view_u64(operation, cols, "column count")?;
        let lda_u64 = view_u64(operation, lda, "leading dimension")?;
        let matrix_offset_u64 = view_u64(operation, matrix_offset, "matrix offset")?;
        let src_len = view_u64(operation, src_view.len, "source view length")?;
        let src_offset = view_u64(operation, src_view.offset, "source offset")?;
        let src_stride = view_u64(operation, src_view.stride, "source stride")?;
        let src_indices_offset =
            view_u64(operation, src_indices_view.offset, "source-index offset")?;
        let src_indices_stride =
            view_u64(operation, src_indices_view.stride, "source-index stride")?;
        let dst_len = view_u64(operation, dst_view.len, "destination view length")?;
        let dst_offset = view_u64(operation, dst_view.offset, "destination offset")?;
        let dst_stride = view_u64(operation, dst_view.stride, "destination stride")?;
        let dst_indices_offset = view_u64(
            operation,
            dst_indices_view.offset,
            "destination-index offset",
        )?;
        let dst_indices_stride = view_u64(
            operation,
            dst_indices_view.stride,
            "destination-index stride",
        )?;
        let rows_launch = u32::try_from(rows).map_err(|_| BackendError::InvalidArgument {
            operation,
            reason: "row count exceeds CUDA launch range".into(),
        })?;
        let matrix_raw = matrix.raw().ok_or(BackendError::InvalidArgument {
            operation,
            reason: "matrix buffer is unexpectedly empty".into(),
        })?;
        let src_raw = src.raw().ok_or(BackendError::InvalidArgument {
            operation,
            reason: "source buffer is unexpectedly empty".into(),
        })?;
        let src_indices_raw = src_indices.raw().ok_or(BackendError::InvalidArgument {
            operation,
            reason: "source-index buffer is unexpectedly empty".into(),
        })?;
        let dst_raw = dst.raw_mut().ok_or(BackendError::InvalidArgument {
            operation,
            reason: "destination buffer is unexpectedly empty".into(),
        })?;
        let dst_indices_raw = dst_indices.raw().ok_or(BackendError::InvalidArgument {
            operation,
            reason: "destination-index buffer is unexpectedly empty".into(),
        })?;
        self.runtime_stats.record_kernel_launch();
        unsafe {
            self.stream
                .launch_builder(&kernels.indexed_dense_matvec_accum_strided_c64)
                .arg(matrix_raw)
                .arg(src_raw)
                .arg(src_indices_raw)
                .arg(dst_raw)
                .arg(dst_indices_raw)
                .arg(&rows_u64)
                .arg(&cols_u64)
                .arg(&lda_u64)
                .arg(&src_len)
                .arg(&dst_len)
                .arg(&matrix_offset_u64)
                .arg(&src_offset)
                .arg(&src_stride)
                .arg(&src_indices_offset)
                .arg(&src_indices_stride)
                .arg(&dst_offset)
                .arg(&dst_stride)
                .arg(&dst_indices_offset)
                .arg(&dst_indices_stride)
                .launch(LaunchConfig {
                    grid_dim: (rows_launch, 1, 1),
                    block_dim: (1, 1, 1),
                    shared_mem_bytes: 0,
                })
                .map_err(|error| {
                    backend_driver_launch_error(
                        &self.pending_error,
                        operation,
                        format!("{error:?}"),
                    )
                })?;
        }
        Ok(())
    }

