    /// Evaluate regular Helmholtz `(G, H, H^T, E)` triangle-pair integrals
    /// on CUDA using the same fixed 4-point rule as the Metal implementation.
    /// Fallible native BEM pair dispatch.
    ///
    /// The legacy method below preserves its historical infallible API, but
    /// backend-facing callers must use this entry point so allocation,
    /// launch, synchronization, and readback failures remain typed.
    pub fn try_bem_regular_pair_c32_batch(
        &self,
        pairs: &[BemRegularPairIn],
        wave_number: f32,
        harmonic_factor: f32,
    ) -> BackendResult<Vec<BemRegularPairOut>> {
        self.check_pending_error()?;
        validate_bem_regular_pair_inputs(pairs, wave_number, harmonic_factor)?;
        let n = pairs.len();
        if n == 0 {
            return Ok(Vec::new());
        }
        if self.bem_kernels.is_none() {
            return Err(BackendError::HostFallback {
                backend: "cuda",
                operation: "bem_regular_pair_c32_batch",
                scalar: std::any::type_name::<Complex32>(),
            });
        }
        let kernels = self
            .bem_kernels
            .as_ref()
            .ok_or(BackendError::HostFallback {
                backend: "cuda",
                operation: "bem_regular_pair_c32_batch",
                scalar: std::any::type_name::<Complex32>(),
            })?;
        let n_pairs = u64::try_from(n).map_err(|_| BackendError::InvalidArgument {
            operation: "bem_regular_pair_c32_batch",
            reason: "batch length exceeds u64".into(),
        })?;
        let launch_n = u32::try_from(n).map_err(|_| BackendError::InvalidArgument {
            operation: "bem_regular_pair_c32_batch",
            reason: "batch length exceeds CUDA launch limit".into(),
        })?;

        let mut in_buf = self
            .raw_alloc::<BemRegularPairIn>(n)
            .map_err(BackendError::from)?;
        self.try_copy_h2d(pairs, &mut in_buf)?;
        let mut out_buf = self
            .raw_alloc::<BemRegularPairOut>(n)
            .map_err(BackendError::from)?;
        let in_raw = in_buf.raw().ok_or(BackendError::InvalidArgument {
            operation: "bem_regular_pair_c32_batch",
            reason: "input buffer is empty after allocation".into(),
        })?;
        let out_raw = out_buf.raw_mut().ok_or(BackendError::InvalidArgument {
            operation: "bem_regular_pair_c32_batch",
            reason: "output buffer is empty after allocation".into(),
        })?;
        let config = LaunchConfig::for_num_elems(launch_n);
        self.try_inject_failure(CudaFailureInjectionPoint::Launch)?;
        self.runtime_stats.record_kernel_launch();
        unsafe {
            self.stream
                .launch_builder(&kernels.regular_pair_c32)
                .arg(in_raw)
                .arg(out_raw)
                .arg(&wave_number)
                .arg(&harmonic_factor)
                .arg(&n_pairs)
                .launch(config)
                .map_err(|error| {
                    backend_driver_launch_error(
                        &self.pending_error,
                        "bem_regular_pair_c32_batch",
                        format!("{error:?}"),
                    )
                })?;
        }
        self.try_synchronize()?;
        let (mut out, _staging_guard) =
            try_host_staging_vec(&self.staging_stats, n, "bem_regular_pair host output")?;
        self.try_copy_d2h(&out_buf, &mut out)?;
        validate_bem_regular_pair_outputs(&out)?;
        Ok(out)
    }

