    /// Infallible compatibility wrapper.  Callers requiring device residency
    /// must use [`Self::try_bem_regular_pair_c64_batch`], which rejects an
    /// unavailable kernel instead of silently running the CPU reference.
    pub fn bem_regular_pair_c64_batch(
        &self,
        pairs: &[BemRegularPairInF64],
        wave_number: f64,
        harmonic_factor: f64,
    ) -> Vec<BemRegularPairOutF64> {
        match self.try_bem_regular_pair_c64_batch(pairs, wave_number, harmonic_factor) {
            Ok(result) => result,
            Err(error) => {
                self.record_pending_error(error.clone());
                log::error!(
                    target: "sonium_compute::cuda",
                    "CUDA double-precision BEM regular-pair evaluation failed: {error}"
                );
                Vec::new()
            }
        }
    }

    /// Enqueue a constant-triangle exterior field evaluation into a caller's
    /// device buffer.  Inputs and output remain device-resident; the checked
    /// field operator synchronizes and publishes into its caller output only
    /// after this launch succeeds.
    pub(crate) fn try_bem_field_c64_device(
        &self,
        elements: &Buffer<BemFieldElementC64, CudaBackend>,
        points: &Buffer<BemFieldPointC64, CudaBackend>,
        output: &mut Buffer<Complex64, CudaBackend>,
        wave_number: f64,
        harmonic_factor: f64,
        pressure_factor: f64,
    ) -> BackendResult<()> {
        self.check_pending_error()?;
        let operation = "bem_field_c64_device";
        if points.len() != output.len() {
            return Err(BackendError::InvalidArgument {
                operation,
                reason: format!(
                    "point and output lengths must match ({} vs {})",
                    points.len(),
                    output.len()
                ),
            });
        }
        if elements.is_empty() {
            return Err(BackendError::InvalidArgument {
                operation,
                reason: "element buffer must not be empty".into(),
            });
        }
        if !wave_number.is_finite() || !harmonic_factor.is_finite() || !pressure_factor.is_finite()
        {
            return Err(BackendError::InvalidArgument {
                operation,
                reason: "field parameters must be finite".into(),
            });
        }
        if points.is_empty() {
            return Ok(());
        }
        let kernels = self.bem_kernels.as_ref().ok_or(BackendError::Unsupported {
            backend: "cuda",
            operation,
            scalar: "Complex64",
        })?;
        let n_elements =
            u64::try_from(elements.len()).map_err(|_| BackendError::InvalidArgument {
                operation,
                reason: "element count exceeds CUDA kernel range".into(),
            })?;
        let n_points = u32::try_from(points.len()).map_err(|_| BackendError::InvalidArgument {
            operation,
            reason: "point count exceeds CUDA launch range".into(),
        })?;
        let elements_raw = elements.raw().raw().ok_or(BackendError::InvalidArgument {
            operation,
            reason: "element buffer is unexpectedly empty".into(),
        })?;
        let points_raw = points.raw().raw().ok_or(BackendError::InvalidArgument {
            operation,
            reason: "point buffer is unexpectedly empty".into(),
        })?;
        let output_raw = output
            .raw_mut()
            .raw_mut()
            .ok_or(BackendError::InvalidArgument {
                operation,
                reason: "output buffer is unexpectedly empty".into(),
            })?;
        let block_size = 128_u32;
        let grid_size = n_points.div_ceil(block_size);
        let no_pressure_traces = 0_u64;
        let no_velocity_traces = 0_u64;
        self.try_inject_failure(CudaFailureInjectionPoint::Launch)?;
        self.runtime_stats.record_kernel_launch();
        unsafe {
            self.stream
                .launch_builder(&kernels.field_c64)
                .arg(elements_raw)
                .arg(&no_pressure_traces)
                .arg(&no_velocity_traces)
                .arg(points_raw)
                .arg(output_raw)
                .arg(&wave_number)
                .arg(&harmonic_factor)
                .arg(&pressure_factor)
                .arg(&n_elements)
                .arg(&(u64::from(n_points)))
                .arg(&0_u64)
                .arg(&1_u64)
                .arg(&0_u64)
                .arg(&1_u64)
                .launch(LaunchConfig {
                    grid_dim: (grid_size, 1, 1),
                    block_dim: (block_size, 1, 1),
                    shared_mem_bytes: 0,
                })
                .map_err(|error| {
                    backend_driver_launch_error(
                        &self.pending_error,
                        operation,
                        format!("{error:?}"),
                    )
                })?;
        }
        Ok(())
    }

