    /// Enqueue a precomputed-quadrature BEM pair batch over checked strided
    /// pair and output views.  Pair/sample geometry and results remain
    /// device-resident; this entry point only binds validated pointers and
    /// never allocates staging memory or performs a transfer.
    pub fn try_bem_quadrature_pair_c64_device_view(
        &self,
        pairs: &CudaBuffer<BemQuadraturePairC64>,
        pairs_view: BufferView,
        samples: &CudaBuffer<BemQuadratureSampleC64>,
        output: &mut CudaBuffer<BemRegularPairOutF64>,
        output_view: BufferView,
        wave_number: f64,
        harmonic_factor: f64,
    ) -> BackendResult<()> {
        self.check_pending_error()?;
        let operation = "bem_quadrature_pair_c64_device_view";
        if pairs_view.len != output_view.len {
            return Err(BackendError::InvalidArgument {
                operation,
                reason: format!(
                    "pair and output view lengths must match ({} vs {})",
                    pairs_view.len, output_view.len
                ),
            });
        }
        validate_cuda_buffer_view(operation, pairs, pairs_view)?;
        validate_cuda_buffer_view(operation, output, output_view)?;
        if !wave_number.is_finite() || !harmonic_factor.is_finite() {
            return Err(BackendError::InvalidArgument {
                operation,
                reason: "wave number and harmonic factor must be finite".into(),
            });
        }
        let n_pairs = view_u64(operation, pairs_view.len, "pair view length")?;
        if n_pairs == 0 {
            return Ok(());
        }
        if samples.len == 0 {
            return Err(BackendError::InvalidArgument {
                operation,
                reason: "non-empty pair view requires a non-empty sample buffer".into(),
            });
        }
        let kernels = self.bem_kernels.as_ref().ok_or(BackendError::Unsupported {
            backend: "cuda",
            operation,
            scalar: "Complex64",
        })?;
        let launch_pairs = u32::try_from(n_pairs).map_err(|_| BackendError::InvalidArgument {
            operation,
            reason: "pair count exceeds CUDA launch range".into(),
        })?;
        let n_samples = u64::try_from(samples.len).map_err(|_| BackendError::InvalidArgument {
            operation,
            reason: "sample count exceeds CUDA kernel range".into(),
        })?;
        let pair_offset = view_u64(operation, pairs_view.offset, "pair offset")?;
        let pair_stride = view_u64(operation, pairs_view.stride, "pair stride")?;
        let output_offset = view_u64(operation, output_view.offset, "output offset")?;
        let output_stride = view_u64(operation, output_view.stride, "output stride")?;
        let pairs_raw = pairs.raw().ok_or(BackendError::InvalidArgument {
            operation,
            reason: "pair buffer is unexpectedly empty".into(),
        })?;
        let samples_raw = samples.raw().ok_or(BackendError::InvalidArgument {
            operation,
            reason: "sample buffer is unexpectedly empty".into(),
        })?;
        let output_raw = output.raw_mut().ok_or(BackendError::InvalidArgument {
            operation,
            reason: "output buffer is unexpectedly empty".into(),
        })?;
        let block_size = 128_u32;
        let grid_size = launch_pairs.div_ceil(block_size);
        self.try_inject_failure(CudaFailureInjectionPoint::Launch)?;
        self.runtime_stats.record_kernel_launch();
        unsafe {
            self.stream
                .launch_builder(&kernels.quadrature_pair_c64)
                .arg(pairs_raw)
                .arg(samples_raw)
                .arg(output_raw)
                .arg(&wave_number)
                .arg(&harmonic_factor)
                .arg(&n_samples)
                .arg(&n_pairs)
                .arg(&pair_offset)
                .arg(&pair_stride)
                .arg(&output_offset)
                .arg(&output_stride)
                .launch(LaunchConfig {
                    grid_dim: (grid_size, 1, 1),
                    block_dim: (block_size, 1, 1),
                    shared_mem_bytes: 0,
                })
                .map_err(|error| {
                    backend_driver_launch_error(
                        &self.pending_error,
                        operation,
                        format!("{error:?}"),
                    )
                })?;
        }
        Ok(())
    }

