    fn capabilities(&self) -> BackendCapabilities {
        let cast = if self.cast_kernels.is_some() {
            CapabilityState::Native
        } else {
            CapabilityState::HostStagedFallback
        };
        let gather = if self.cast_kernels.is_some() && self.validation_kernels.is_some() {
            CapabilityState::Native
        } else {
            CapabilityState::HostStagedFallback
        };
        let multi_dot = cuda_multi_dot_capability(self.multi_dot_kernels.is_some());
        // Without the fused kernel module, axpy_many still executes through
        // repeated cuBLAS AXPY calls: it is vendor-native, not host-staged.
        let axpy_many = cuda_axpy_many_capability(self.multi_dot_kernels.is_some());
        let multi_dot_strided = cuda_multi_dot_capability(self.multi_dot_kernels.is_some());
        let fft_c32 = if self.fft.is_some() {
            CapabilityState::VendorNative
        } else {
            CapabilityState::Unsupported
        };
        let fft_c64 = fft_c32;
        let cuda_quadrature_pair = ScalarCapabilities::new(
            CapabilityState::Unsupported,
            CapabilityState::Unsupported,
            CapabilityState::Unsupported,
            if self.bem_kernels.is_some() {
                CapabilityState::Native
            } else {
                CapabilityState::Unsupported
            },
        );
        // The current BEM H-matrix/FMM adapters construct trees, admissibility
        // lists, and compressed factors in sonium-bem before uploading them.
        // Keep that setup boundary explicit; only the uploaded action data and
        // reusable workspaces are native CUDA operations today.
        let cuda_hierarchical_setup = ScalarCapabilities::new(
            CapabilityState::Unsupported,
            CapabilityState::Unsupported,
            CapabilityState::Unsupported,
            if self.fmm_kernels.is_some() {
                CapabilityState::HostSharedFallback
            } else {
                CapabilityState::Unsupported
            },
        );

        BackendCapabilities {
            backend_name: "cuda",
            blas1: ScalarCapabilities::splat(CapabilityState::VendorNative),
            gemv: ScalarCapabilities::splat(CapabilityState::VendorNative),
            gemm: ScalarCapabilities::splat(CapabilityState::VendorNative),
            trsm: ScalarCapabilities::splat(CapabilityState::VendorNative),
            syrk: ScalarCapabilities::splat(CapabilityState::VendorNative),
            fft: cuda_fft_capabilities(fft_c32, fft_c64),
            real_fft: cuda_real_transform_capabilities(self.fft.is_some()),
            dct: cuda_real_transform_capabilities(
                self.fft.is_some() && self.real_transform_kernels.is_some(),
            ),
            dst: cuda_real_transform_capabilities(
                self.fft.is_some() && self.real_transform_kernels.is_some(),
            ),
            csr_spmv: ScalarCapabilities::splat(CapabilityState::VendorNative),
            csr_spmm: ScalarCapabilities::splat(CapabilityState::VendorNative),
            csr_transpose: ScalarCapabilities::splat(CapabilityState::VendorNative),
            axpy_many: ScalarCapabilities::splat(axpy_many),
            multi_dot: ScalarCapabilities::splat(multi_dot),
            multi_dot_strided: ScalarCapabilities::splat(multi_dot_strided),
            basis_axpy_strided: ScalarCapabilities::splat(multi_dot_strided),
            basis_project_out_strided: ScalarCapabilities::splat(multi_dot_strided),
            gather4_weighted: ScalarCapabilities::splat(gather),
            segmented_reduce: ScalarCapabilities::splat(
                if self.local_kernels.is_some() && self.validation_kernels.is_some() {
                    CapabilityState::Native
                } else {
                    CapabilityState::HostStagedFallback
                },
            ),
            batched_local_contract: ScalarCapabilities::splat(if self.local_kernels.is_some() {
                CapabilityState::Native
            } else {
                CapabilityState::HostStagedFallback
            }),
            reduction: ReductionCapabilities::new(
                ScalarCapabilities::splat(CapabilityState::VendorNative),
                ScalarCapabilities::splat(CapabilityState::HostStagedFallback),
            ),
            precision_cast: PrecisionCastCapabilities::splat(cast),
            bem_regular_pair_c32: if self.bem_kernels.is_some() {
                CapabilityState::Native
            } else {
                CapabilityState::HostStagedFallback
            },
            bem_regular_pair_c64: if self.bem_kernels.is_some() {
                CapabilityState::Native
            } else {
                CapabilityState::Unsupported
            },
            bem: BemCapabilities {
                regular_pair_c32: if self.bem_kernels.is_some() {
                    CapabilityState::Native
                } else {
                    CapabilityState::HostStagedFallback
                },
                regular_pair_c64: if self.bem_kernels.is_some() {
                    CapabilityState::Native
                } else {
                    CapabilityState::Unsupported
                },
                // Constant-panel Tri3 regular, quasi-singular, Duffy bulk,
                // and regularised hypersingular-edge arithmetic all use the
                // Complex64 quadrature kernel.  Tree construction,
                // admissibility, and compression remain an explicit host-side
                // boundary in the current H-matrix API; uploaded blocks and
                // every supported action are device-resident after setup.
                near_pair: cuda_quadrature_pair,
                singular_pair: cuda_quadrature_pair,
                hypersingular_pair: cuda_quadrature_pair,
                field_evaluation: ScalarCapabilities::new(
                    CapabilityState::Unsupported,
                    CapabilityState::Unsupported,
                    CapabilityState::Unsupported,
                    if self.bem_kernels.is_some() {
                        CapabilityState::Native
                    } else {
                        CapabilityState::Unsupported
                    },
                ),
                hmatrix_setup: cuda_hierarchical_setup,
                hmatrix: ScalarCapabilities::new(
                    CapabilityState::Unsupported,
                    CapabilityState::Unsupported,
                    CapabilityState::Unsupported,
                    if self.fmm_kernels.is_some() {
                        CapabilityState::Native
                    } else {
                        CapabilityState::Unsupported
                    },
                ),
                fmm_setup: cuda_hierarchical_setup,
                fmm: ScalarCapabilities::new(
                    CapabilityState::Unsupported,
                    CapabilityState::Unsupported,
                    CapabilityState::Unsupported,
                    if self.fmm_kernels.is_some() {
                        CapabilityState::Native
                    } else {
                        CapabilityState::Unsupported
                    },
                ),
            },
        }
    }

