    fn try_fft_in_place<T: BufferElement>(
        &self,
        buffer: &mut Self::Buffer<T>,
        fft_len: usize,
        inverse: bool,
    ) -> BackendResult<()> {
        self.check_pending_error()?;
        let is_c32 = TypeId::of::<T>() == TypeId::of::<Complex32>();
        let is_c64 = TypeId::of::<T>() == TypeId::of::<Complex64>();
        if !is_c32 && !is_c64 {
            return Err(BackendError::Unsupported {
                backend: "cuda",
                operation: "fft",
                scalar: std::any::type_name::<T>(),
            });
        }
        let fft = self.fft.as_ref().ok_or(BackendError::Unsupported {
            backend: "cuda",
            operation: "fft",
            scalar: std::any::type_name::<T>(),
        })?;
        // Faults at resource/launch boundaries are checked before cuFFT sees
        // the buffer. This keeps injected failures deterministic and ensures
        // an in-place destination remains unchanged on rejection.
        self.try_inject_failure(CudaFailureInjectionPoint::DescriptorCreation)?;
        self.try_inject_failure(CudaFailureInjectionPoint::Allocation)?;
        self.try_inject_failure(CudaFailureInjectionPoint::Launch)?;
        if is_c32 {
            // SAFETY: the TypeId check proves T is Complex32; both buffer
            // types have identical representation and only differ in
            // PhantomData.
            let buffer_c32 =
                unsafe { &mut *(buffer as *mut CudaBuffer<T> as *mut CudaBuffer<Complex32>) };
            self.runtime_stats.record_library_operation();
            fft.exec_c32(buffer_c32, fft_len, inverse)
        } else {
            // SAFETY: the TypeId check proves T is Complex64; both buffer
            // types have identical representation and only differ in
            // PhantomData.
            let buffer_c64 =
                unsafe { &mut *(buffer as *mut CudaBuffer<T> as *mut CudaBuffer<Complex64>) };
            self.runtime_stats.record_library_operation();
            fft.exec_c64(buffer_c64, fft_len, inverse)
        }
    }

