    fn raw_alloc<T: BufferElement>(&self, len: usize) -> Result<Self::Buffer<T>, OomError> {
        if len == 0 {
            return Ok(CudaBuffer {
                inner: None,
                len: 0,
                _allocation: None,
                _marker: PhantomData,
            });
        }
        self.try_inject_failure(CudaFailureInjectionPoint::Allocation)
            .map_err(backend_error_to_oom)?;
        let bytes = len
            .checked_mul(std::mem::size_of::<T>())
            .ok_or_else(|| OomError::Invalid("alloc size overflow".into()))?;
        let allocation = self.allocation_stats.try_reserve(bytes)?;
        let inner = self
            .stream
            .alloc_zeros::<u8>(bytes)
            .map_err(driver_to_oom)?;
        Ok(CudaBuffer {
            inner: Some(inner),
            len,
            _allocation: Some(allocation),
            _marker: PhantomData,
        })
    }

    unsafe fn raw_alloc_uninitialized<T: BufferElement>(
        &self,
        len: usize,
    ) -> Result<Self::Buffer<T>, OomError> {
        if len == 0 {
            return Ok(CudaBuffer {
                inner: None,
                len: 0,
                _allocation: None,
                _marker: PhantomData,
            });
        }
        self.try_inject_failure(CudaFailureInjectionPoint::Allocation)
            .map_err(backend_error_to_oom)?;
        let bytes = len
            .checked_mul(std::mem::size_of::<T>())
            .ok_or_else(|| OomError::Invalid("alloc size overflow".into()))?;
        // SAFETY: this backend method is the uninitialized allocation path;
        // callers must initialize the returned buffer before any read.
        let allocation = self.allocation_stats.try_reserve(bytes)?;
        let inner = unsafe { self.stream.alloc::<u8>(bytes) }.map_err(driver_to_oom)?;
        Ok(CudaBuffer {
            inner: Some(inner),
            len,
            _allocation: Some(allocation),
            _marker: PhantomData,
        })
    }

