    #[allow(clippy::too_many_arguments)]
    fn try_syrk<T: DeviceScalar>(
        &self,
        uplo: TrsmUplo,
        trans: Transpose,
        n: usize,
        k: usize,
        alpha: T,
        a: &Self::Buffer<T>,
        lda: usize,
        beta: T,
        c: &mut Self::Buffer<T>,
        ldc: usize,
    ) -> BackendResult<()> {
        self.check_pending_error()?;
        let capabilities = self.capabilities();
        crate::backend::require_scalar_capability::<T>(
            capabilities.backend_name,
            "syrk",
            capabilities.syrk,
        )?;
        crate::backend::validate_syrk_args(trans, n, k, a.len, lda, c.len, ldc)?;
        let (a_rows, a_cols) = match trans {
            Transpose::NoTrans => (n, k),
            Transpose::Trans | Transpose::ConjTrans => (k, n),
        };
        self.checked_dense_matrix_descriptor(a, a_rows, a_cols, lda, ViewAliasing::ReadOnly)?;
        self.checked_dense_matrix_descriptor(c, n, n, ldc, ViewAliasing::Disjoint)?;
        crate::backend::require_finite_scalar("syrk", "alpha", alpha)?;
        crate::backend::require_finite_scalar("syrk", "beta", beta)?;
        if n == 0 {
            return Ok(());
        }
        let tid = TypeId::of::<T>();
        let is_complex = tid == TypeId::of::<Complex32>() || tid == TypeId::of::<Complex64>();
        // Complex `ConjTrans` is the Hermitian update (conjugated factor).
        // With real `alpha`/`beta` the row-major `C = alpha*A^H*A + beta*C`
        // (A k×n) is the col-major `C' = alpha*A'*A'^H + beta*C'` with
        // `A' = A^T` (n×k), i.e. cuBLAS herk with `CUBLAS_OP_N` and a
        // flipped fill mode. The herk path follows cuBLAS diagonal
        // semantics (imaginary parts of the diagonal are set to zero, so
        // pass a Hermitian `C`, as with any herk). Complex scalars keep
        // the host fallback: the result is not Hermitian then, so no herk
        // spelling applies. Real `ConjTrans` folds to `Trans` in the
        // wrappers below.
        let use_herk = if is_complex && matches!(trans, Transpose::ConjTrans) {
            if tid == TypeId::of::<Complex32>() {
                let (ar, br) = unsafe {
                    (
                        val_cast::<T, Complex32>(alpha),
                        val_cast::<T, Complex32>(beta),
                    )
                };
                ar.im == 0.0 && br.im == 0.0
            } else if tid == TypeId::of::<Complex64>() {
                let (ar, br) = unsafe {
                    (
                        val_cast::<T, Complex64>(alpha),
                        val_cast::<T, Complex64>(beta),
                    )
                };
                ar.im == 0.0 && br.im == 0.0
            } else {
                false
            }
        } else {
            false
        };
        if is_complex && matches!(trans, Transpose::ConjTrans) && !use_herk {
            return crate::backend::host_syrk(self, uplo, trans, n, k, alpha, a, lda, beta, c, ldc);
        }
        let n_i = i32::try_from(n).map_err(|_| BackendError::InvalidArgument {
            operation: "syrk",
            reason: format!("n={n} exceeds cuBLAS i32 range"),
        })?;
        let k_i = i32::try_from(k).map_err(|_| BackendError::InvalidArgument {
            operation: "syrk",
            reason: format!("k={k} exceeds cuBLAS i32 range"),
        })?;
        let lda_i = i32::try_from(lda).map_err(|_| BackendError::InvalidArgument {
            operation: "syrk",
            reason: format!("lda={lda} exceeds cuBLAS i32 range"),
        })?;
        let ldc_i = i32::try_from(ldc).map_err(|_| BackendError::InvalidArgument {
            operation: "syrk",
            reason: format!("ldc={ldc} exceeds cuBLAS i32 range"),
        })?;
        let (ap, _ag) = buf_ptr(a, &self.stream).ok_or_else(|| BackendError::InvalidArgument {
            operation: "syrk",
            reason: "non-empty operand has no device allocation".into(),
        })?;
        let (cp, _cg) =
            buf_ptr_mut(c, &self.stream).ok_or_else(|| BackendError::InvalidArgument {
                operation: "syrk",
                reason: "non-empty output has no device allocation".into(),
            })?;
        self.runtime_stats.record_library_operation();
        let status = unsafe {
            if tid == TypeId::of::<f32>() {
                blas23::syrk_f32(
                    self.blas,
                    uplo,
                    trans,
                    n_i,
                    k_i,
                    val_cast::<T, f32>(alpha),
                    ap,
                    lda_i,
                    val_cast::<T, f32>(beta),
                    cp,
                    ldc_i,
                )
            } else if tid == TypeId::of::<f64>() {
                blas23::syrk_f64(
                    self.blas,
                    uplo,
                    trans,
                    n_i,
                    k_i,
                    val_cast::<T, f64>(alpha),
                    ap,
                    lda_i,
                    val_cast::<T, f64>(beta),
                    cp,
                    ldc_i,
                )
            } else if tid == TypeId::of::<Complex32>() {
                if use_herk {
                    blas23::herk_c32(
                        self.blas,
                        uplo,
                        n_i,
                        k_i,
                        val_cast::<T, Complex32>(alpha).re,
                        ap,
                        lda_i,
                        val_cast::<T, Complex32>(beta).re,
                        cp,
                        ldc_i,
                    )
                } else {
                    blas23::syrk_c32(
                        self.blas,
                        uplo,
                        trans,
                        n_i,
                        k_i,
                        val_cast::<T, Complex32>(alpha),
                        ap,
                        lda_i,
                        val_cast::<T, Complex32>(beta),
                        cp,
                        ldc_i,
                    )
                }
            } else if tid == TypeId::of::<Complex64>() {
                if use_herk {
                    blas23::herk_c64(
                        self.blas,
                        uplo,
                        n_i,
                        k_i,
                        val_cast::<T, Complex64>(alpha).re,
                        ap,
                        lda_i,
                        val_cast::<T, Complex64>(beta).re,
                        cp,
                        ldc_i,
                    )
                } else {
                    blas23::syrk_c64(
                        self.blas,
                        uplo,
                        trans,
                        n_i,
                        k_i,
                        val_cast::<T, Complex64>(alpha),
                        ap,
                        lda_i,
                        val_cast::<T, Complex64>(beta),
                        cp,
                        ldc_i,
                    )
                }
            } else {
                return Err(BackendError::Unsupported {
                    backend: "cuda",
                    operation: "syrk",
                    scalar: "unsupported",
                });
            }
        };
        if status == cublas_sys::cublasStatus_t::CUBLAS_STATUS_SUCCESS {
            Ok(())
        } else {
            Err(self.cublas_error("syrk", status))
        }
    }

    fn gemv<T: DeviceScalar>(
        &self,
        op: Transpose,
        m: usize,
        n: usize,
        alpha: T,
        a: &Self::Buffer<T>,
        lda: usize,
        x: &Self::Buffer<T>,
        beta: T,
        y: &mut Self::Buffer<T>,
    ) {
        if let Err(error) = self.try_gemv(op, m, n, alpha, a, lda, x, beta, y) {
            self.record_pending_error(error);
        }
    }

    fn gemv_batched<T: DeviceScalar>(&self, batch: &mut [GemvBatch<'_, Self::Buffer<T>, T>]) {
        if let Err(error) = self.check_pending_error() {
            self.record_pending_error(error);
            return;
        }
        let native = if batch.len() < 2 {
            false
        } else {
            match self.try_gemv_batched_native(batch) {
                Ok(native) => native,
                Err(error) => {
                    self.record_pending_error(error);
                    false
                }
            }
        };
        if !native {
            for item in batch {
                self.gemv(
                    item.op, item.m, item.n, item.alpha, item.a, item.lda, item.x, item.beta,
                    item.y,
                );
            }
        }
    }

    fn try_gemv_batched<T: DeviceScalar>(
        &self,
        batch: &mut [GemvBatch<'_, Self::Buffer<T>, T>],
    ) -> BackendResult<()> {
        self.check_pending_error()?;
        for item in batch.iter() {
            crate::backend::validate_gemv_args(
                item.op,
                item.m,
                item.n,
                item.a.len(),
                item.lda,
                item.x.len(),
                item.y.len(),
            )?;
            let (stored_rows, stored_cols) = match item.op {
                Transpose::NoTrans => (item.m, item.n),
                Transpose::Trans | Transpose::ConjTrans => (item.n, item.m),
            };
            self.checked_dense_matrix_descriptor(
                item.a,
                stored_rows,
                stored_cols,
                item.lda,
                ViewAliasing::ReadOnly,
            )?;
            self.checked_dense_vector_descriptor(item.x, ViewAliasing::ReadOnly)?;
            self.checked_dense_vector_descriptor(item.y, ViewAliasing::Disjoint)?;
        }
        for item in batch.iter() {
            crate::backend::require_finite_scalar("gemv_batched", "alpha", item.alpha)?;
            crate::backend::require_finite_scalar("gemv_batched", "beta", item.beta)?;
        }
        if batch.len() < 2 {
            for item in batch {
                self.try_gemv(
                    item.op, item.m, item.n, item.alpha, item.a, item.lda, item.x, item.beta,
                    item.y,
                )?;
            }
            return Ok(());
        }
        if self.try_gemv_batched_native(batch)? {
            return Ok(());
        }
        for item in batch {
            self.try_gemv(
                item.op, item.m, item.n, item.alpha, item.a, item.lda, item.x, item.beta, item.y,
            )?;
        }
        Ok(())
    }

