// ---------------------------------------------------------------------------
// Type-id casting helper
// ---------------------------------------------------------------------------

/// Reinterpret `T` as `U` when `TypeId::of::<T>() == TypeId::of::<U>()`.
///
/// SAFETY: caller must verify the type-id match.
#[inline]
unsafe fn val_cast<T: Copy + 'static, U: Copy + 'static>(v: T) -> U {
    debug_assert_eq!(TypeId::of::<T>(), TypeId::of::<U>());
    debug_assert_eq!(std::mem::size_of::<T>(), std::mem::size_of::<U>());
    unsafe { std::mem::transmute_copy(&v) }
}

/// Reinterpret a typed CUDA buffer when the caller has already checked
/// `TypeId::of::<T>() == TypeId::of::<U>()`.
#[inline]
unsafe fn cast_buf<T: BufferElement, U: BufferElement>(b: &CudaBuffer<T>) -> &CudaBuffer<U> {
    debug_assert_eq!(TypeId::of::<T>(), TypeId::of::<U>());
    unsafe { &*(b as *const CudaBuffer<T> as *const CudaBuffer<U>) }
}

/// Reinterpret a mutable typed CUDA buffer after the caller has checked the
/// scalar `TypeId` match.
#[inline]
unsafe fn cast_buf_mut<T: BufferElement, U: BufferElement>(
    b: &mut CudaBuffer<T>,
) -> &mut CudaBuffer<U> {
    debug_assert_eq!(TypeId::of::<T>(), TypeId::of::<U>());
    unsafe { &mut *(b as *mut CudaBuffer<T> as *mut CudaBuffer<U>) }
}
